function t(k, v) {
  let s = (I18N[LINGUA_CORRENTE] && I18N[LINGUA_CORRENTE][k]) || I18N.it[k] || k;
  if (v) Object.keys(v).forEach(x => { s = s.split('{' + x + '}').join(v[x]); });
  return s;
}

/* ===== v0.17 — Informativa privacy (tutte le lingue; traduzioni non verificate da madrelingua) ===== */
D("priv_titolo", "Privacy: dove vanno i dati", "Privacy: where the data goes", "Datenschutz: Wohin gehen die Daten", "Confidentialité : où vont les données", "Privacidad: adónde van los datos", "Confidențialitate: unde ajung datele", "Privatësia: ku shkojnë të dhënat", "الخصوصية: إلى أين تذهب البيانات", "隐私：数据去向");
D("priv_intro", "AI.st.ain non ha un server e non ha account: non raccogliamo dati. Qui sotto trovi cosa resta sul dispositivo e cosa viene inviato a servizi esterni quando usi le funzioni AI o la voce.", "AI.st.ain has no server and no accounts: we collect no data. Below you can see what stays on the device and what is sent to external services when you use the AI features or the voice.", "AI.st.ain hat keinen Server und keine Konten: Wir sammeln keine Daten. Hier steht, was auf dem Gerät bleibt und was an externe Dienste gesendet wird, wenn du die KI-Funktionen oder die Stimme nutzt.", "AI.st.ain n’a pas de serveur ni de comptes : nous ne collectons aucune donnée. Voici ce qui reste sur l’appareil et ce qui est envoyé à des services externes quand tu utilises les fonctions IA ou la voix.", "AI.st.ain no tiene servidor ni cuentas: no recogemos datos. Aquí ves qué se queda en el dispositivo y qué se envía a servicios externos cuando usas las funciones de IA o la voz.", "AI.st.ain nu are server și nu are conturi: nu colectăm date. Mai jos vezi ce rămâne pe dispozitiv și ce se trimite către servicii externe când folosești funcțiile AI sau vocea.", "AI.st.ain nuk ka server dhe nuk ka llogari: nuk mbledhim të dhëna. Më poshtë gjen çfarë mbetet në pajisje dhe çfarë dërgohet te shërbime të jashtme kur përdor funksionet e AI-së ose zërin.", "لا يملك AI.st.ain خادمًا ولا حسابات: نحن لا نجمع أي بيانات. تجد أدناه ما يبقى على الجهاز وما يُرسل إلى خدمات خارجية عند استخدام ميزات الذكاء الاصطناعي أو الصوت.", "AI.st.ain 没有服务器，也没有账号：我们不收集任何数据。下面说明哪些数据留在设备上，以及使用 AI 功能或语音时哪些会发送给外部服务。");
D("priv_dev_t", "Resta sul dispositivo", "Stays on the device", "Bleibt auf dem Gerät", "Reste sur l’appareil", "Se queda en el dispositivo", "Rămâne pe dispozitiv", "Mbetet në pajisje", "يبقى على الجهاز", "留在设备上");
D("priv_dev", "Profili dei ragazzi (nome, livello, DSA, aspetto) e PIN, salvati solo come impronta|Capitoli, riassunti, mappe, test, esercizi, «Il mio riassunto», risultati, punti, statistiche e calendario verifiche|La chiave API, salvata cifrata|Le foto non vengono salvate: restano in memoria solo il tempo di inviarle|Il testo dell’interrogazione orale non viene archiviato: si conserva solo data e percentuale|Le copie di sicurezza vanno dove le salvi tu (non contengono chiavi né PIN)", "Children’s profiles (name, school level, learning difficulties, look) and PINs, stored only as a fingerprint|Chapters, summaries, maps, tests, exercises, “My summary”, results, points, statistics and test calendar|The API key, stored encrypted|Photos are not saved: they stay in memory only while being sent|The text of the oral practice is not archived: only the date and percentage are kept|Backups go wherever you save them (they contain no keys or PINs)", "Profile der Kinder (Name, Schulstufe, Lernschwierigkeiten, Aussehen) und PINs, nur als Prüfwert gespeichert|Kapitel, Zusammenfassungen, Mindmaps, Tests, Übungen, „Meine Zusammenfassung“, Ergebnisse, Punkte, Statistiken und Prüfungskalender|Der API-Schlüssel, verschlüsselt gespeichert|Fotos werden nicht gespeichert: Sie bleiben nur so lange im Speicher, bis sie gesendet sind|Der Text der mündlichen Übung wird nicht archiviert: Nur Datum und Prozentwert werden gespeichert|Sicherungskopien liegen dort, wo du sie speicherst (ohne Schlüssel und PINs)", "Profils des enfants (prénom, niveau scolaire, troubles de l’apprentissage, apparence) et codes PIN, enregistrés seulement sous forme d’empreinte|Chapitres, résumés, cartes, tests, exercices, « Mon résumé », résultats, points, statistiques et calendrier des contrôles|La clé API, enregistrée chiffrée|Les photos ne sont pas enregistrées : elles restent en mémoire le temps de l’envoi|Le texte de l’interrogation orale n’est pas archivé : seules la date et le pourcentage sont conservés|Les sauvegardes vont là où tu les enregistres (sans clés ni PIN)", "Perfiles de los niños (nombre, nivel escolar, dificultades de aprendizaje, aspecto) y PIN, guardados solo como huella|Capítulos, resúmenes, mapas, pruebas, ejercicios, «Mi resumen», resultados, puntos, estadísticas y calendario de exámenes|La clave API, guardada cifrada|Las fotos no se guardan: quedan en memoria solo el tiempo de enviarlas|El texto del examen oral no se archiva: solo se guardan la fecha y el porcentaje|Las copias de seguridad van donde las guardes tú (sin claves ni PIN)", "Profilurile copiilor (nume, nivel școlar, dificultăți de învățare, aspect) și PIN-urile, salvate doar sub formă de amprentă|Capitole, rezumate, hărți, teste, exerciții, „Rezumatul meu”, rezultate, puncte, statistici și calendarul lucrărilor|Cheia API, salvată criptat|Pozele nu se salvează: rămân în memorie doar cât timp sunt trimise|Textul examinării orale nu se arhivează: se păstrează doar data și procentul|Copiile de siguranță ajung unde le salvezi tu (nu conțin chei sau PIN-uri)", "Profilet e fëmijëve (emri, niveli shkollor, vështirësitë e të nxënit, pamja) dhe PIN-et, të ruajtura vetëm si shenjë e koduar|Kapitujt, përmbledhjet, hartat, testet, ushtrimet, «Përmbledhja ime», rezultatet, pikët, statistikat dhe kalendari i verifikimeve|Çelësi API, i ruajtur i enkriptuar|Fotot nuk ruhen: mbeten në memorie vetëm sa për t’u dërguar|Teksti i pyetjes me gojë nuk arkivohet: ruhen vetëm data dhe përqindja|Kopjet rezervë shkojnë ku i ruan ti (nuk përmbajnë çelësa ose PIN-e)", "ملفات الأطفال (الاسم والمستوى الدراسي وصعوبات التعلّم والمظهر) والأرقام السرية، وتُحفظ على شكل بصمة فقط|الفصول والملخصات والخرائط والاختبارات والتمارين و«ملخصي» والنتائج والنقاط والإحصاءات وجدول الامتحانات|مفتاح API، ويُحفظ مشفّرًا|لا تُحفظ الصور: تبقى في الذاكرة فقط أثناء إرسالها|لا يُؤرشف نص الاستجواب الشفهي: يُحفظ فقط التاريخ والنسبة المئوية|النسخ الاحتياطية تذهب إلى المكان الذي تحفظها فيه (ولا تحتوي مفاتيح ولا أرقامًا سرية)", "孩子的档案（姓名、年级、学习障碍、外观）和 PIN 码，PIN 码只以指纹形式保存|章节、摘要、思维导图、测验、练习、“我的摘要”、成绩、积分、统计和考试日历|API 密钥，加密保存|照片不会保存：只在发送期间留在内存中|口语练习的文字不会存档：只保存日期和百分比|备份保存在你选择的位置（不含密钥和 PIN 码）");
D("priv_ai_t", "Va al servizio AI scelto dal genitore (non succede con Ollama o LM Studio sul tuo PC)", "Goes to the AI service chosen by the parent (not with Ollama or LM Studio on your PC)", "Geht an den vom Elternteil gewählten KI-Dienst (nicht bei Ollama oder LM Studio auf deinem PC)", "Va au service IA choisi par le parent (pas avec Ollama ou LM Studio sur ton PC)", "Va al servicio de IA elegido por el padre o la madre (no ocurre con Ollama o LM Studio en tu PC)", "Merge la serviciul AI ales de părinte (nu se întâmplă cu Ollama sau LM Studio pe PC-ul tău)", "Shkon te shërbimi AI i zgjedhur nga prindi (nuk ndodh me Ollama ose LM Studio në kompjuterin tënd)", "يذهب إلى خدمة الذكاء الاصطناعي التي اختارها ولي الأمر (ولا يحدث ذلك مع Ollama أو LM Studio على جهازك)", "发送给家长选择的 AI 服务（在你电脑上使用 Ollama 或 LM Studio 时不会发生）");
D("priv_ai", "Foto delle pagine del libro, degli esercizi e dello svolgimento. Se sul quaderno c’è scritto il nome, parte con la foto|Il testo dei capitoli e le risposte scritte o dette dal ragazzo (esercizi, riassunto, interrogazione)|Livello scolastico, lingua e i DSA selezionati, per adattare i contenuti. Il nome del ragazzo non viene inviato|La chiave API, solo per autenticarti presso quel servizio", "Photos of book pages, exercises and the student’s work. If a name is written in the notebook, it goes with the photo|The text of the chapters and the child’s written or spoken answers (exercises, summary, oral practice)|School level, language and the selected learning difficulties, to adapt the content. The child’s name is not sent|The API key, only to authenticate with that service", "Fotos von Buchseiten, Aufgaben und eigener Lösung. Steht der Name im Heft, geht er mit dem Foto mit|Der Text der Kapitel und die geschriebenen oder gesprochenen Antworten des Kindes (Übungen, Zusammenfassung, mündliche Übung)|Schulstufe, Sprache und die gewählten Lernschwierigkeiten, um die Inhalte anzupassen. Der Name des Kindes wird nicht gesendet|Der API-Schlüssel, nur zur Anmeldung bei diesem Dienst", "Photos des pages du livre, des exercices et du travail de l’élève. Si le nom est écrit sur le cahier, il part avec la photo|Le texte des chapitres et les réponses écrites ou dites par l’enfant (exercices, résumé, interrogation orale)|Niveau scolaire, langue et troubles de l’apprentissage sélectionnés, pour adapter les contenus. Le prénom de l’enfant n’est pas envoyé|La clé API, uniquement pour t’authentifier auprès de ce service", "Fotos de las páginas del libro, de los ejercicios y del trabajo del alumno. Si el nombre está escrito en el cuaderno, sale con la foto|El texto de los capítulos y las respuestas escritas o dichas por el niño (ejercicios, resumen, examen oral)|Nivel escolar, idioma y dificultades de aprendizaje seleccionadas, para adaptar los contenidos. El nombre del niño no se envía|La clave API, solo para autenticarte en ese servicio", "Poze cu paginile cărții, exerciții și rezolvarea ta. Dacă numele e scris pe caiet, pleacă odată cu poza|Textul capitolelor și răspunsurile scrise sau spuse de copil (exerciții, rezumat, examinare orală)|Nivelul școlar, limba și dificultățile de învățare selectate, pentru adaptarea conținutului. Numele copilului nu se trimite|Cheia API, doar pentru autentificarea la acel serviciu", "Fotot e faqeve të librit, të ushtrimeve dhe të zgjidhjes sate. Nëse emri është shkruar në fletore, shkon bashkë me foton|Teksti i kapitujve dhe përgjigjet e shkruara ose të thëna nga fëmija (ushtrime, përmbledhje, pyetje me gojë)|Niveli shkollor, gjuha dhe vështirësitë e zgjedhura të nxënies, për përshtatjen e përmbajtjes. Emri i fëmijës nuk dërgohet|Çelësi API, vetëm për t’u identifikuar te ai shërbim", "صور صفحات الكتاب والتمارين وحلّ الطالب. إذا كان الاسم مكتوبًا على الدفتر فسيُرسل مع الصورة|نص الفصول والإجابات المكتوبة أو المنطوقة للطفل (التمارين والملخص والاستجواب الشفهي)|المستوى الدراسي واللغة وصعوبات التعلّم المحددة، لتكييف المحتوى. لا يُرسل اسم الطفل|مفتاح API، فقط للتحقق من هويتك لدى تلك الخدمة", "课本页面、练习题和孩子作业的照片。如果本子上写了名字，会随照片一起发送|章节文字，以及孩子写下或说出的回答（练习、摘要、口语练习）|年级、语言和所选的学习障碍，用于调整内容。孩子的姓名不会发送|API 密钥，仅用于向该服务验证身份");
D("priv_voce_t", "Va al produttore del browser (Google o Microsoft), solo se usi la voce", "Goes to the browser maker (Google or Microsoft), only if you use the voice", "Geht an den Browser-Hersteller (Google oder Microsoft), nur wenn du die Stimme nutzt", "Va au fabricant du navigateur (Google ou Microsoft), seulement si tu utilises la voix", "Va al fabricante del navegador (Google o Microsoft), solo si usas la voz", "Merge la producătorul browserului (Google sau Microsoft), doar dacă folosești vocea", "Shkon te prodhuesi i shfletuesit (Google ose Microsoft), vetëm nëse përdor zërin", "يذهب إلى الشركة المصنّعة للمتصفح (Google أو Microsoft)، فقط إذا استخدمت الصوت", "发送给浏览器厂商（Google 或 Microsoft），仅在使用语音时");
D("priv_voce", "L’audio, per il riconoscimento vocale (quiz a voce e interrogazione)|Il testo letto ad alta voce, se scegli una voce «di rete» (online): con una voce del dispositivo non esce nulla", "The audio, for speech recognition (voice quiz and oral practice)|The text read aloud, if you choose a “network” (online) voice: with a device voice nothing leaves", "Das Audio für die Spracherkennung (Sprach-Quiz und mündliche Übung)|Der vorgelesene Text, wenn du eine „Netzwerk“-Stimme (online) wählst: Bei einer Gerätestimme verlässt nichts das Gerät", "L’audio, pour la reconnaissance vocale (quiz vocal et interrogation orale)|Le texte lu à voix haute, si tu choisis une voix « réseau » (en ligne) : avec une voix de l’appareil, rien ne sort", "El audio, para el reconocimiento de voz (cuestionario por voz y examen oral)|El texto leído en voz alta, si eliges una voz «de red» (en línea): con una voz del dispositivo no sale nada", "Sunetul, pentru recunoașterea vocală (test vocal și examinare orală)|Textul citit cu voce tare, dacă alegi o voce „de rețea” (online): cu o voce a dispozitivului nu iese nimic", "Audioja, për njohjen e zërit (kuiz me zë dhe pyetje me gojë)|Teksti i lexuar me zë, nëse zgjedh një zë «në rrjet» (online): me një zë të pajisjes nuk del asgjë", "الصوت، للتعرّف على الكلام (الاختبار الصوتي والاستجواب الشفهي)|النص المقروء بصوت عالٍ، إذا اخترت صوتًا «شبكيًا» (عبر الإنترنت): ومع صوت الجهاز لا يخرج شيء", "用于语音识别的音频（语音测验和口语练习）|朗读的文字，如果选择了“网络”（在线）语音：使用设备本地语音则不会外发");
D("priv_gh_t", "Va a GitHub, quando apri o aggiorni l’app", "Goes to GitHub, when you open or update the app", "Geht an GitHub, wenn du die App öffnest oder aktualisierst", "Va à GitHub, quand tu ouvres ou mets à jour l’app", "Va a GitHub, cuando abres o actualizas la app", "Merge la GitHub, când deschizi sau actualizezi aplicația", "Shkon te GitHub, kur hap ose përditëson aplikacionin", "يذهب إلى GitHub عند فتح التطبيق أو تحديثه", "打开或更新应用时发送给 GitHub");
D("priv_gh", "Solo la normale richiesta dei file del sito (indirizzo IP e tipo di browser, come qualsiasi sito). Nessun dato dei ragazzi", "Only the normal request for the site’s files (IP address and browser type, like any website). No data about the children", "Nur die normale Anfrage der Website-Dateien (IP-Adresse und Browsertyp, wie bei jeder Website). Keine Daten der Kinder", "Seulement la demande normale des fichiers du site (adresse IP et type de navigateur, comme tout site). Aucune donnée des enfants", "Solo la petición normal de los archivos del sitio (dirección IP y tipo de navegador, como cualquier sitio). Ningún dato de los niños", "Doar cererea obișnuită a fișierelor site-ului (adresa IP și tipul de browser, ca la orice site). Nicio dată a copiilor", "Vetëm kërkesa normale për skedarët e faqes (adresa IP dhe lloji i shfletuesit, si në çdo faqe). Asnjë të dhënë të fëmijëve", "فقط الطلب المعتاد لملفات الموقع (عنوان IP ونوع المتصفح، كأي موقع). لا توجد أي بيانات للأطفال", "只有网站文件的常规请求（IP 地址和浏览器类型，与任何网站一样）。不含孩子的任何数据");
D("priv_no_t", "Non c’è", "Not there", "Gibt es nicht", "Il n’y a pas", "No hay", "Nu există", "Nuk ka", "غير موجود", "没有的东西");
D("priv_no", "Nessun server nostro, nessun account, nessuna statistica d’uso, nessun tracciamento, nessun font o script da altri siti", "No server of ours, no accounts, no usage statistics, no tracking, no fonts or scripts from other sites", "Kein eigener Server, keine Konten, keine Nutzungsstatistik, kein Tracking, keine Schriften oder Skripte von anderen Seiten", "Pas de serveur à nous, pas de comptes, pas de statistiques d’usage, pas de suivi, pas de police ni de script venant d’autres sites", "Ningún servidor propio, ninguna cuenta, ninguna estadística de uso, ningún rastreo, ninguna fuente ni script de otros sitios", "Niciun server propriu, niciun cont, nicio statistică de utilizare, nicio urmărire, niciun font sau script de pe alte site-uri", "Asnjë server i yni, asnjë llogari, asnjë statistikë përdorimi, asnjë gjurmim, asnjë shkronjë ose skript nga faqe të tjera", "لا خادم خاص بنا، ولا حسابات، ولا إحصاءات استخدام، ولا تتبّع، ولا خطوط أو نصوص برمجية من مواقع أخرى", "没有我们自己的服务器、没有账号、没有使用统计、没有跟踪、没有来自其他网站的字体或脚本");
D("priv_nota", "Cosa fa il servizio AI con i contenuti dipende dalle sue condizioni: alcuni piani gratuiti possono usarli per migliorare i modelli, altri no. Leggi le condizioni del servizio che scegli. Chi usa l’app per i propri figli è responsabile di queste scelte; per altri ragazzi serve il consenso dei genitori.", "What the AI service does with the content depends on its terms: some free plans may use it to improve their models, others do not. Read the terms of the service you choose. Whoever uses the app for their own children is responsible for these choices; for other children, parental consent is needed.", "Was der KI-Dienst mit den Inhalten macht, hängt von dessen Bedingungen ab: Manche kostenlosen Tarife dürfen sie zur Verbesserung der Modelle nutzen, andere nicht. Lies die Bedingungen des gewählten Dienstes. Wer die App für seine Kinder nutzt, ist für diese Entscheidungen verantwortlich; für andere Kinder braucht es die Einwilligung der Eltern.", "Ce que le service IA fait des contenus dépend de ses conditions : certaines offres gratuites peuvent les utiliser pour améliorer les modèles, d’autres non. Lis les conditions du service choisi. Qui utilise l’app pour ses propres enfants est responsable de ces choix ; pour d’autres enfants, il faut l’accord des parents.", "Lo que el servicio de IA hace con los contenidos depende de sus condiciones: algunos planes gratuitos pueden usarlos para mejorar los modelos, otros no. Lee las condiciones del servicio que elijas. Quien usa la app con sus propios hijos es responsable de estas decisiones; para otros niños hace falta el consentimiento de los padres.", "Ce face serviciul AI cu conținutul depinde de condițiile lui: unele planuri gratuite pot folosi conținutul pentru a îmbunătăți modelele, altele nu. Citește condițiile serviciului ales. Cine folosește aplicația pentru proprii copii răspunde de aceste alegeri; pentru alți copii e nevoie de acordul părinților.", "Çfarë bën shërbimi AI me përmbajtjen varet nga kushtet e tij: disa plane falas mund ta përdorin për të përmirësuar modelet, të tjerat jo. Lexo kushtet e shërbimit që zgjedh. Kush e përdor aplikacionin për fëmijët e vet është përgjegjës për këto zgjedhje; për fëmijë të tjerë nevojitet pëlqimi i prindërve.", "ما تفعله خدمة الذكاء الاصطناعي بالمحتوى يعتمد على شروطها: بعض الخطط المجانية قد تستخدمه لتحسين النماذج وبعضها لا. اقرأ شروط الخدمة التي تختارها. من يستخدم التطبيق مع أبنائه مسؤول عن هذه الخيارات؛ ومع أطفال آخرين تلزم موافقة الوالدين.", "AI 服务如何处理内容取决于其条款：有些免费套餐可能用内容改进模型，有些不会。请阅读你所选服务的条款。为自己孩子使用应用的人需对这些选择负责；用于其他孩子需要家长同意。");
D("priv_btn", "Privacy: cosa resta qui e cosa va in cloud", "Privacy: what stays here and what goes to the cloud", "Datenschutz: was bleibt hier, was geht in die Cloud", "Confidentialité : ce qui reste ici et ce qui va dans le cloud", "Privacidad: qué se queda aquí y qué va a la nube", "Confidențialitate: ce rămâne aici și ce ajunge în cloud", "Privatësia: çfarë mbetet këtu dhe çfarë shkon në cloud", "الخصوصية: ما يبقى هنا وما يذهب إلى السحابة", "隐私：哪些留在这里，哪些进入云端");
D("priv_ho_letto", "Ho letto l’informativa privacy e ho capito cosa viene inviato ai servizi esterni", "I have read the privacy notice and understand what is sent to external services", "Ich habe die Datenschutzinformation gelesen und verstanden, was an externe Dienste gesendet wird", "J’ai lu l’information sur la confidentialité et compris ce qui est envoyé aux services externes", "He leído la información de privacidad y entiendo qué se envía a servicios externos", "Am citit informarea de confidențialitate și am înțeles ce se trimite către servicii externe", "E kam lexuar informimin për privatësinë dhe kam kuptuar çfarë dërgohet te shërbimet e jashtme", "قرأتُ إشعار الخصوصية وفهمتُ ما يُرسل إلى الخدمات الخارجية", "我已阅读隐私说明，并明白哪些内容会发送给外部服务");
D("priv_obbl", "Per continuare spunta la conferma di aver letto l’informativa privacy.", "To continue, tick the confirmation that you have read the privacy notice.", "Um fortzufahren, bestätige, dass du die Datenschutzinformation gelesen hast.", "Pour continuer, coche la confirmation de lecture de l’information sur la confidentialité.", "Para continuar, marca que has leído la información de privacidad.", "Pentru a continua, bifează că ai citit informarea de confidențialitate.", "Për të vazhduar, shëno që e ke lexuar informimin për privatësinë.", "للمتابعة، ضع علامة تأكيد قراءة إشعار الخصوصية.", "要继续，请勾选已阅读隐私说明。");
D("priv_foto", "Le foto vengono inviate al servizio AI scelto dal genitore. Evita di inquadrare nomi o dati personali.", "Photos are sent to the AI service chosen by the parent. Avoid capturing names or personal data.", "Fotos werden an den vom Elternteil gewählten KI-Dienst gesendet. Vermeide Namen oder persönliche Daten im Bild.", "Les photos sont envoyées au service IA choisi par le parent. Évite de photographier des noms ou des données personnelles.", "Las fotos se envían al servicio de IA elegido por el padre o la madre. Evita fotografiar nombres o datos personales.", "Pozele se trimit către serviciul AI ales de părinte. Evită să fotografiezi nume sau date personale.", "Fotot dërgohen te shërbimi AI i zgjedhur nga prindi. Shmang emrat ose të dhënat personale në foto.", "تُرسل الصور إلى خدمة الذكاء الاصطناعي التي اختارها ولي الأمر. تجنّب تصوير الأسماء أو البيانات الشخصية.", "照片会发送给家长选择的 AI 服务。请避免拍到姓名或个人信息。");
D("priv_indietro", "Indietro", "Back", "Zurück", "Retour", "Atrás", "Înapoi", "Mbrapa", "رجوع", "返回");
D("priv_breve", "I dati restano sul dispositivo; solo quando usi l’AI o la voce, foto, testi e audio vanno al servizio scelto.", "Data stays on the device; only when you use AI or voice do photos, texts and audio go to the chosen service.", "Die Daten bleiben auf dem Gerät; nur wenn du KI oder Stimme nutzt, gehen Fotos, Texte und Audio an den gewählten Dienst.", "Les données restent sur l’appareil ; seulement quand tu utilises l’IA ou la voix, photos, textes et audio vont au service choisi.", "Los datos se quedan en el dispositivo; solo cuando usas la IA o la voz, fotos, textos y audio van al servicio elegido.", "Datele rămân pe dispozitiv; doar când folosești AI sau vocea, pozele, textele și sunetul ajung la serviciul ales.", "Të dhënat mbeten në pajisje; vetëm kur përdor AI-në ose zërin, fotot, tekstet dhe audioja shkojnë te shërbimi i zgjedhur.", "تبقى البيانات على الجهاز؛ ولا تذهب الصور والنصوص والصوت إلى الخدمة المختارة إلا عند استخدام الذكاء الاصطناعي أو الصوت.", "数据留在设备上；只有使用 AI 或语音时，照片、文字和音频才会发送给所选服务。");
D("priv_dsa_nota", "I DSA selezionati partono come istruzioni di adattamento che ne riportano il nome (es. «Dislessia: frasi brevi…»), ma senza il nome del ragazzo: il servizio AI non sa a chi si riferiscono. Se preferisci che non partano, disattiva l’interruttore nelle impostazioni della famiglia: font e spaziatura si adattano comunque sul dispositivo, ma i contenuti generati saranno meno su misura.", "The selected learning difficulties are sent as adaptation instructions that include their name (e.g. “Dyslexia: short sentences…”), but without the child’s name: the AI service does not know who they refer to. If you prefer they are not sent, turn off the switch in the family settings: font and spacing still adapt on the device, but generated content will be less tailored.", "Die gewählten Lernschwierigkeiten werden als Anpassungsanweisungen mit ihrem Namen gesendet (z. B. „Legasthenie: kurze Sätze…“), aber ohne den Namen des Kindes: Der KI-Dienst weiß nicht, auf wen sie sich beziehen. Wenn du das nicht möchtest, schalte den Schalter in den Familieneinstellungen aus: Schrift und Abstände passen sich weiterhin auf dem Gerät an, die erzeugten Inhalte sind aber weniger maßgeschneidert.", "Les troubles sélectionnés sont envoyés comme consignes d’adaptation qui en citent le nom (ex. « Dyslexie : phrases courtes… »), mais sans le prénom de l’enfant : le service IA ne sait pas à qui ils se rapportent. Si tu préfères qu’ils ne partent pas, désactive l’interrupteur dans les réglages de la famille : police et espacement s’adaptent quand même sur l’appareil, mais les contenus générés seront moins personnalisés.", "Las dificultades seleccionadas se envían como instrucciones de adaptación que incluyen su nombre (p. ej. «Dislexia: frases cortas…»), pero sin el nombre del niño: el servicio de IA no sabe a quién se refieren. Si prefieres que no se envíen, desactiva el interruptor en los ajustes de la familia: la fuente y el espaciado se adaptan igualmente en el dispositivo, pero los contenidos generados estarán menos personalizados.", "Dificultățile selectate se trimit ca instrucțiuni de adaptare care le includ numele (ex. „Dislexie: propoziții scurte…”), dar fără numele copilului: serviciul AI nu știe cui se referă. Dacă preferi să nu se trimită, dezactivează comutatorul din setările familiei: fontul și spațierea se adaptează oricum pe dispozitiv, dar conținutul generat va fi mai puțin personalizat.", "Vështirësitë e zgjedhura dërgohen si udhëzime përshtatjeje që e përmbajnë emrin e tyre (p.sh. «Disleksia: fjali të shkurtra…»), por pa emrin e fëmijës: shërbimi AI nuk e di për kë i përkasin. Nëse parapëlqen të mos dërgohen, çaktivizo çelësin te cilësimet e familjes: shkronjat dhe hapësirat përshtaten prapë në pajisje, por përmbajtja e gjeneruar do të jetë më pak e personalizuar.", "تُرسل صعوبات التعلّم المحددة كتعليمات تكييف تتضمن اسمها (مثل «عسر القراءة: جمل قصيرة…») ولكن دون اسم الطفل: فلا تعرف خدمة الذكاء الاصطناعي لمن تعود. وإن فضّلت ألا تُرسل، فعطّل المفتاح في إعدادات العائلة: يستمر تكييف الخط والتباعد على الجهاز، لكن المحتوى المُنشأ سيكون أقل ملاءمة.", "所选的学习障碍会作为包含其名称的调整指令发送（例如“阅读障碍：用短句……”），但不含孩子的姓名：AI 服务不知道这是指谁。如果你不希望发送，请在家庭设置中关闭该开关：字体和间距仍会在设备上自动调整，但生成的内容会不那么贴合。");
D("dsa_ai_lbl", "Invia all’AI i DSA selezionati, per adattare i contenuti (senza il nome del ragazzo)", "Send the selected learning difficulties to the AI to adapt content (without the child’s name)", "Gewählte Lernschwierigkeiten an die KI senden, um Inhalte anzupassen (ohne Namen des Kindes)", "Envoyer à l’IA les troubles sélectionnés pour adapter les contenus (sans le prénom de l’enfant)", "Enviar a la IA las dificultades seleccionadas para adaptar los contenidos (sin el nombre del niño)", "Trimite către AI dificultățile selectate pentru adaptarea conținutului (fără numele copilului)", "Dërgo te AI vështirësitë e zgjedhura për të përshtatur përmbajtjen (pa emrin e fëmijës)", "إرسال صعوبات التعلّم المحددة إلى الذكاء الاصطناعي لتكييف المحتوى (دون اسم الطفل)", "向 AI 发送所选学习障碍以调整内容（不含孩子姓名）");
D("dsa_ai_nota", "Se lo disattivi, il servizio AI non riceve nessuna informazione sui DSA.", "If you turn it off, the AI service receives no information about learning difficulties.", "Wenn du es ausschaltest, erhält der KI-Dienst keine Angaben zu Lernschwierigkeiten.", "Si tu le désactives, le service IA ne reçoit aucune information sur les troubles.", "Si lo desactivas, el servicio de IA no recibe ninguna información sobre las dificultades.", "Dacă îl dezactivezi, serviciul AI nu primește nicio informație despre dificultăți.", "Nëse e çaktivizon, shërbimi AI nuk merr asnjë informacion për vështirësitë.", "إذا عطّلته فلن تتلقى خدمة الذكاء الاصطناعي أي معلومات عن صعوبات التعلّم.", "关闭后，AI 服务不会收到任何学习障碍信息。");

/* v0.21 capitoli lunghi a blocchi */
D("prog_pagine", "{i} pagine su {n}", "{i} of {n} pages", "{i} von {n} Seiten", "{i} pages sur {n}", "{i} de {n} páginas", "{i} din {n} pagini", "{i} nga {n} faqe", "{i} من {n} صفحة", "{n} 页中的第 {i} 页");
D("blocchi_nota", "Sono tante pagine: AI.st.ain le legge a blocchi di {b} pagine ({n} blocchi) e poi unisce tutto in un solo capitolo. Ci vorrà qualche minuto: lascia aperta la pagina.", "That is a lot of pages: AI.st.ain reads them in blocks of {b} pages ({n} blocks) and then joins everything into one chapter. It will take a few minutes: keep the page open.", "Das sind viele Seiten: AI.st.ain liest sie in Blöcken zu je {b} Seiten ({n} Blöcke) und fügt dann alles zu einem Kapitel zusammen. Das dauert einige Minuten: lass die Seite geöffnet.", "Ce sont beaucoup de pages : AI.st.ain les lit par blocs de {b} pages ({n} blocs) puis réunit tout en un seul chapitre. Cela prendra quelques minutes : laisse la page ouverte.", "Son muchas páginas: AI.st.ain las lee en bloques de {b} páginas ({n} bloques) y luego lo une todo en un solo capítulo. Tardará unos minutos: deja la página abierta.", "Sunt multe pagini: AI.st.ain le citește în blocuri de {b} pagini ({n} blocuri) și apoi unește totul într-un singur capitol. Va dura câteva minute: ține pagina deschisă.", "Janë shumë faqe: AI.st.ain i lexon në blloqe me {b} faqe ({n} blloqe) dhe pastaj i bashkon të gjitha në një kapitull. Do të zgjasë disa minuta: mbaje faqen të hapur.", "هذه صفحات كثيرة: يقرؤها AI.st.ain على دفعات من {b} صفحات ({n} دفعات) ثم يجمع كل شيء في فصل واحد. سيستغرق ذلك بضع دقائق: أبقِ الصفحة مفتوحة.", "页数较多：AI.st.ain 会按每 {b} 页一组（共 {n} 组）阅读，然后合并成一个章节。需要几分钟，请保持页面打开。");
D("avv_parte_mancante", "Le foto dalla {a} alla {b} non sono state elaborate (errore temporaneo): caricale di nuovo in un nuovo lavoro.", "Photos {a} to {b} were not processed (temporary error): upload them again as a new job.", "Die Fotos {a} bis {b} wurden nicht verarbeitet (vorübergehender Fehler): lade sie erneut als neue Aufgabe hoch.", "Les photos {a} à {b} n’ont pas été traitées (erreur temporaire) : recharge-les dans un nouveau travail.", "Las fotos de la {a} a la {b} no se procesaron (error temporal): vuelve a subirlas en un trabajo nuevo.", "Pozele {a}–{b} nu au fost procesate (eroare temporară): încarcă-le din nou într-o lucrare nouă.", "Fotot {a}–{b} nuk u përpunuan (gabim i përkohshëm): ngarkoji përsëri në një punë të re.", "لم تُعالج الصور من {a} إلى {b} (خطأ مؤقت): أعد رفعها في عمل جديد.", "第 {a} 到 {b} 张照片未能处理（临时错误）：请作为新任务重新上传。");

/* v0.23 tutorial e questionario DSA (it/en; le altre lingue ripiegano sull'inglese) */
DE("tour_titolo", "Guida all’uso", "How to use the app");
DE("tour_btn", "Come si usa", "How it works");
DE("tour_n", "{i} di {n}", "{i} of {n}");
DE("tour_avanti", "Avanti", "Next");
DE("tour_indietro", "Indietro", "Back");
DE("tour_salta", "Salta", "Skip");
DE("tour_fine", "Ho capito", "Got it");
DE("tour_altrove", "La guida si apre dalla pagina iniziale, da una materia, da un capitolo e dall’area genitori.", "The guide opens from the home page, a subject, a chapter and the parents’ area.");
DE("tour_brand", "Questo è AI.st.ain: toccalo per tornare sempre alla pagina iniziale.", "This is AI.st.ain: tap it to go back to the home page at any time.");
DE("tour_testo", "Con A− e A+ riduci o ingrandisci il testo.", "Use A− and A+ to make the text smaller or bigger.");
DE("tour_aspetto", "Qui cambi tema, carattere e spaziatura per leggere più comodo.", "Change theme, font and spacing here to read more comfortably.");
DE("tour_addmat", "Per cominciare aggiungi le tue materie: tocca un nome qui sotto oppure scrivine uno.", "To start, add your subjects: tap a name below or type your own.");
DE("tour_mat", "Ogni riquadro è una materia: aprila per aggiungere capitoli ed esercizi.", "Each tile is a subject: open it to add chapters and exercises.");
DE("tour_gen", "L’area genitori (con PIN) serve per collegare l’AI, vedere i progressi e fare le copie di sicurezza.", "The parents’ area (PIN protected) is for connecting the AI, checking progress and making backups.");
DE("tour_ancora", "Se vuoi rivedere questa guida, tocca il punto interrogativo.", "To see this guide again, tap the question mark.");
DE("tour_nuovocap", "Fotografa le pagine di un capitolo: AI.st.ain prepara riassunto, schema, spiegazioni e test.", "Photograph the pages of a chapter: AI.st.ain prepares summary, outline, explanations and quizzes.");
DE("tour_nuovoes", "Fotografa un esercizio: ti guida passo passo, senza darti la soluzione.", "Photograph an exercise: it guides you step by step without giving the solution.");
DE("tour_controllo", "Hai già svolto un esercizio? Fotografalo e fatti controllare il ragionamento.", "Already solved an exercise? Photograph it and have your reasoning checked.");
DE("tour_tabs", "Le schede del capitolo: riassunto, schema, mappa, spiegazioni, glossario, allenamento, interrogazione e test finale.", "The chapter tabs: summary, outline, map, explanations, glossary, practice, oral practice and final quiz.");
DE("tour_ascolta", "Con questo tasto il capitolo ti viene letto ad alta voce.", "This button reads the chapter aloud to you.");
DE("tour_figlio", "Qui aggiungi il profilo di un ragazzo: livello, aiuti per lo studio e PIN.", "Add a child’s profile here: school level, study supports and PIN.");
DE("tour_fam", "Nelle impostazioni della famiglia colleghi il servizio AI e scegli la lingua.", "In the family settings you connect the AI service and choose the language.");
DE("tour_priv", "Qui trovi cosa resta sul dispositivo e cosa viene inviato ai servizi esterni.", "Here you see what stays on the device and what is sent to external services.");
DE("tour_backup", "Salva ogni tanto una copia di sicurezza: se cambi dispositivo la ripristini da qui.", "Save a backup now and then: if you change device, restore it from here.");
DE("dsaq_promo_t", "Capire come studi meglio", "Understand how you study best");
DE("dsaq_promo", "Un questionario di circa 3 minuti sui segnali che possono far pensare a un DSA. Non è una diagnosi: serve solo a capire se vale la pena approfondire e quali aiuti provare.", "A questionnaire of about 3 minutes on signs that may point to a learning difficulty (SLD). It is not a diagnosis: it only helps decide whether to look further and which supports to try.");
DE("dsaq_promo_btn", "Fai il questionario", "Take the questionnaire");
DE("dsaq_titolo", "Questionario sui segnali di DSA", "Questionnaire on signs of learning difficulties");
DE("dsaq_non_diag", "Non è un test diagnostico e non sostituisce la valutazione di uno specialista.", "This is not a diagnostic test and does not replace an assessment by a specialist.");
DE("dsaq_intro", "Le frasi parlano della persona che studia: rispondi tu oppure un genitore insieme a te. Pensa agli ultimi 6 mesi e a come va nonostante l’impegno. Sono 24 domande, divise in 4 parti.", "The statements are about the person who studies: answer yourself or have a parent answer with you. Think about the last 6 months and how things go despite effort. There are 24 questions in 4 parts.");
DE("dsaq_priv", "Le risposte restano su questo dispositivo: non vengono salvate né inviate a nessuno.", "Answers stay on this device: they are neither saved nor sent to anyone.");
DE("dsaq_inizia", "Inizia", "Start");
DE("dsaq_chiudi", "Chiudi", "Close");
DE("dsaq_avanti", "Avanti", "Next");
DE("dsaq_indietro", "Indietro", "Back");
DE("dsaq_fine", "Vedi il risultato", "See the result");
DE("dsaq_pag", "Parte {i} di {n}", "Part {i} of {n}");
DE("dsaq_scala", "Quanto succede?", "How often does this happen?");
DE("dsaq_mai", "Mai o quasi mai", "Never or almost never");
DE("dsaq_volte", "A volte", "Sometimes");
DE("dsaq_spesso", "Spesso", "Often");
DE("dsaq_tutte", "Rispondi a tutte le domande per continuare.", "Answer all the questions to continue.");
DE("dsaq_risultato", "Risultato", "Result");
DE("dsaq_res_0", "Pochi segnali", "Few signs");
DE("dsaq_res_1", "Alcuni segnali", "Some signs");
DE("dsaq_res_2", "Molti segnali", "Many signs");
DE("dsaq_esito_ok", "Dalle risposte non emergono segnali particolari. Se vedi fatiche che durano nel tempo, puoi rifare il questionario più avanti o parlarne con un insegnante.", "No particular signs emerge from the answers. If you notice difficulties that last over time, you can retake the questionnaire later or talk to a teacher.");
DE("dsaq_esito_si", "Per le aree con più segnali può valere la pena un approfondimento: parlane con il pediatra o con la scuola. Un DSA lo può diagnosticare solo un’équipe specializzata (neuropsichiatra infantile, psicologo) presso la ASL o centri accreditati. Intanto puoi attivare in prova gli aiuti dell’app: li togli quando vuoi.", "For the areas with more signs it may be worth looking further: talk to your paediatrician or the school. A learning difficulty can only be diagnosed by a specialised team (child neuropsychiatrist, psychologist). Meanwhile you can switch on the app’s supports as a trial: you can remove them any time.");
DE("dsaq_piccoli", "Prima della fine della 2ª–3ª elementare una diagnosi di DSA di solito non è ancora possibile: i segnali vanno osservati nel tempo.", "Before the end of 2nd–3rd grade of primary school a diagnosis is usually not yet possible: signs should be observed over time.");
DE("dsaq_altre_cause", "Anche vista o udito, stanchezza, ansia o studiare in una lingua che non è la propria possono dare segnali simili.", "Eyesight or hearing, tiredness, anxiety or studying in a second language can cause similar signs.");
DE("dsaq_attiva", "Attiva in prova gli aiuti suggeriti", "Switch on the suggested supports as a trial");
DE("dsaq_attivati", "Aiuti selezionati: controlla e salva il profilo.", "Supports selected: check and save the profile.");
DE("dq_dislessia_1", "Legge molto più lentamente o con più fatica degli altri.", "Reads much more slowly or with more effort than others.");
DE("dq_dislessia_2", "Mentre legge salta parole o righe, o si perde.", "Skips words or lines while reading, or loses their place.");
DE("dq_dislessia_3", "Confonde lettere simili (b/d, p/q, m/n) o inverte le sillabe.", "Mixes up similar letters (b/d, p/q, m/n) or reverses syllables.");
DE("dq_dislessia_4", "Dopo aver letto un brano fatica a ricordare cosa diceva.", "After reading a passage, struggles to remember what it said.");
DE("dq_dislessia_5", "Evita di leggere ad alta voce o si agita quando deve farlo.", "Avoids reading aloud or gets anxious when asked to.");
DE("dq_dislessia_6", "Studiare su testi lunghi lo stanca molto più degli altri.", "Studying from long texts is much more tiring than for others.");
DE("dq_disortografia_1", "Fa molti errori di ortografia anche in parole semplici e conosciute.", "Makes many spelling mistakes even in simple, familiar words.");
DE("dq_disortografia_2", "Scrive la stessa parola in modi diversi nello stesso testo.", "Spells the same word in different ways in the same text.");
DE("dq_disortografia_3", "Dimentica o sbaglia accenti, apostrofi, doppie e h.", "Forgets or gets wrong accents, apostrophes and double letters.");
DE("dq_disortografia_4", "Mentre scrive omette, aggiunge o scambia lettere o sillabe.", "While writing, leaves out, adds or swaps letters or syllables.");
DE("dq_disortografia_5", "Rileggendo non si accorge dei propri errori.", "When rereading, does not notice their own mistakes.");
DE("dq_disortografia_6", "Sotto dettatura va molto peggio che quando scrive liberamente.", "Does much worse when taking dictation than when writing freely.");
DE("dq_disgrafia_1", "La scrittura a mano è poco leggibile o molto irregolare.", "Handwriting is hard to read or very irregular.");
DE("dq_disgrafia_2", "Scrive lentamente e si stanca presto.", "Writes slowly and tires quickly.");
DE("dq_disgrafia_3", "Stringe forte la penna e dopo poco gli fa male la mano.", "Grips the pen hard and the hand soon hurts.");
DE("dq_disgrafia_4", "Righe storte, spazi irregolari, lettere di dimensioni diverse.", "Crooked lines, uneven spacing, letters of different sizes.");
DE("dq_disgrafia_5", "Copiare dalla lavagna o dal libro è lento e pieno di errori.", "Copying from the board or a book is slow and full of mistakes.");
DE("dq_disgrafia_6", "Evita di scrivere a mano e preferisce molto il computer.", "Avoids handwriting and strongly prefers the computer.");
DE("dq_discalculia_1", "Fatica a ricordare le tabelline e i fatti numerici (per esempio 7+8).", "Struggles to remember times tables and number facts (for example 7+8).");
DE("dq_discalculia_2", "Conta ancora con le dita o a mente anche per calcoli semplici.", "Still counts on fingers or in their head for simple sums.");
DE("dq_discalculia_3", "Confonde i segni (+ − × ÷), incolonna male i numeri o li inverte.", "Mixes up signs (+ − × ÷), lines numbers up badly or reverses them.");
DE("dq_discalculia_4", "Ha difficoltà con orologio, calendario, misure o soldi.", "Has trouble with clocks, calendars, measures or money.");
DE("dq_discalculia_5", "Nei problemi con più passaggi perde il filo.", "Loses the thread in problems with several steps.");
DE("dq_discalculia_6", "Sbaglia i calcoli anche dopo aver capito il ragionamento.", "Makes calculation mistakes even after understanding the reasoning.");

